return ['domain'=>'zinn-connector','plural-forms'=>'nplurals=2; plural=(n != 1);','language'=>'ta_IN','project-id-version'=>'zinn-connector','pot-creation-date'=>'2026-10-01T20:50:35+00:00','po-revision-date'=>'2026-10-01T20:50:35+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Connector'=>'Zinn® Connector','https://zinndigital.com/wordpress-plugins/zinn-connector'=>'https://zinndigital.com/wordpress-plugins/zinn-connector','Connects this WordPress site to Zinn Digital® so scheduled articles can be published to it. Paste a pairing code from your Zinn® dashboard and the plugin sets up its own credential — nothing is copied by hand.'=>'இந்த WordPress தளத்தை Zinn Digital® உடன் இணைக்கிறது, இதன் மூலம் திட்டமிடப்பட்ட கட்டுரைகளை இதில் வெளியிட முடியும். உங்கள் Zinn® கட்டுப்பாட்டகத்திலிருந்து இணைத்தல் குறியீட்டை ஒட்டவும், இந்தச் செருகுநிரல் அதன் சொந்த நற்சான்றிதழை அமைத்துக்கொள்ளும் — எதுவும் கைமுறையாக நகலெடுக்கப்படுவதில்லை.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'சேமிக்கப்பட்டது. அதை மாற்ற புதிய மதிப்பை உள்ளிடவும்.','Filter this list…'=>'இந்தப் பட்டியலை வடிகட்டவும்…','Filter this list'=>'இந்தப் பட்டியலை வடிகட்டவும்','Nothing matches that filter.'=>'அந்த வடிப்பானுடன் எதுவும் பொருந்தவில்லை.','Add a row'=>'வரிசையைச் சேர்க்கவும்','Remove this row'=>'இந்த வரியை நீக்கு','Remove'=>'நீக்குக','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — மேலோட்டம்','Overview'=>'கண்ணோட்டம்','Copied'=>'நகலெடுக்கப்பட்டது','Every Zinn® plugin on this site, and whether it is working.'=>'இந்த தளத்தில் உள்ள ஒவ்வொரு Zinn® செருகுநிரலும், அது செயல்படுகிறதா என்பதும்.','No connection is needed for this plugin.'=>'இந்தச் செருகுநிரலுக்கு எந்த இணைப்பும் தேவையில்லை.','Open settings'=>'அமைப்புகளைத் திறக்கவும்','You do not have permission to change these settings.'=>'இந்த அமைப்புகளை மாற்றுவதற்கு உங்களுக்கு அனுமதி இல்லை.','Settings sections'=>'அமைப்புகள் பிரிவுகள்','Support'=>'ஆதரவு','Save changes'=>'மாற்றங்களைச் சேமி','Tools'=>'கருவிகள்','Export settings'=>'அமைப்புகளை ஏற்றுமதி செய்','Reset to defaults'=>'இயல்புநிலைக்கு மீட்டமை','This puts every setting on this plugin back to its default. Continue?'=>'இது இந்தச் செருகுநிரலின் ஒவ்வொரு அமைப்பையும் அதன் இயல்புநிலைக்கு மாற்றும். தொடர விரும்புகிறீர்களா?','Diagnostics for support'=>'ஆதரவிற்கான கண்டறிதல்','Import a settings file'=>'அமைப்புகள் கோப்பினை இறக்குமதி செய்க','Import'=>'இறக்குமதி செய்','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'ஏற்றுமதி செய்யப்பட்ட கோப்புகளில் கடவுச்சொற்கள், டோக்கன்கள் அல்லது API விசைகள் ஒருபோதும் இருக்காது — புதிய தளத்தில் அவற்றை நீங்கள் மீண்டும் உள்ளிட வேண்டும்.','Settings saved.'=>'அமைப்புகள் சேமிக்கப்பட்டன.','Every setting on this plugin is back to its default.'=>'இந்தச் செருகுநிரலின் ஒவ்வொரு அமைப்பும் அதன் இயல்புநிலைக்குத் திரும்பியது.','Done.'=>'முடிந்தது.','That action is not available.'=>'அந்தச் செயல்பாடு கிடைக்கவில்லை.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'அந்தக் கோப்பைப் படிக்க முடியவில்லை. Zinn® செருகுநிரலிலிருந்து ஏற்றுமதி செய்யப்பட்ட அமைப்புகள் கோப்பைத் தேர்ந்தெடுக்கவும்.','That file is too large to be a settings export.'=>'அந்தக் கோப்பு அமைப்புகள் ஏற்றுமதியாக இருப்பதற்கு மிகவும் பெரியதாக உள்ளது.','That file is not a Zinn® settings export.'=>'அந்தக் கோப்பு ஒரு Zinn® அமைப்புகள் ஏற்றுமதி அல்ல.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'அந்தக் கோப்பு வேறொரு செருகுநிரலில் (%s) இருந்து ஏற்றுமதி செய்யப்பட்டது, எனவே அதை இங்கே இறக்குமதி செய்தால் இந்தச் செருகுநிரலால் புரிந்துகொள்ள முடியாத அமைப்புகள் சேமிக்கப்படும்.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d அமைப்பு இறக்குமதி செய்யப்பட்டது. கடவுச்சொற்கள் மற்றும் API விசைகள் ஒருபோதும் ஏற்றுமதியில் இருக்காது, எனவே அவற்றை மீண்டும் உள்ளிடவும்.' . "\0" . '%d அமைப்புகள் இறக்குமதி செய்யப்பட்டன. கடவுச்சொற்களும் API விசைகளும் ஒருபோதும் ஏற்றுமதியில் இருக்காது, எனவே அவற்றை மீண்டும் உள்ளிடவும்.','The archive would be %1$d MB, over the %2$d MB limit set on this site. Raise the limit, or exclude some folders, on the Zinn Digital® → Connector → Backups screen.'=>'காப்பகம் %1$d MB ஆக இருக்கும், இது இந்த தளத்தில் அமைக்கப்பட்ட %2$d MB வரம்பை விட அதிகம். Zinn Digital® → Connector → Backups திரையில் வரம்பை உயர்த்தவும், அல்லது சில கோப்புறைகளைத் தவிர்க்கவும்.','This site\'s PHP cannot create archives, so a backup could not be made.'=>'இந்த தளத்தின் PHP காப்பகங்களை உருவாக்க முடியாது, எனவே காப்புப்பிரதியை உருவாக்க முடியவில்லை.','Could not create a temporary file.'=>'தற்காலிகக் கோப்பை உருவாக்க முடியவில்லை.','This site\'s files could not be archived.'=>'இந்தத் தளத்தின் கோப்புகளைக் காப்பகப்படுத்த முடியவில்லை.','This site\'s PHP cannot compress archives, so a backup could not be made.'=>'இந்த தளத்தின் PHP-ஆல் காப்பகங்களை சுருக்க முடியாது, எனவே காப்புப்பிரதியை உருவாக்க முடியவில்லை.','A backup of this site needs about %1$s of temporary space and only %2$s is free, so it was not attempted.'=>'இந்த தளத்தின் காப்புப்பிரதிக்கு தோராயமாக %1$s தற்காலிக இடம் தேவைப்படுகிறது மற்றும் %2$s மட்டுமே காலியாக உள்ளது, எனவே இது முயற்சிக்கப்படவில்லை.','This WordPress user cannot publish posts, so a connection made now could not publish either. Sign in as a user who can, and try again.'=>'இந்த WordPress பயனரால் இடுகைகளை வெளியிட முடியாது, எனவே இப்போது ஏற்படுத்தப்படும் இணைப்பாலும் வெளியிட முடியாது. வெளியிடக்கூடிய பயனராக உள்நுழைந்து மீண்டும் முயற்சிக்கவும்.','Application passwords are turned off on this site, so we cannot create a credential. Ask your host to enable them, or connect the site with a password you create yourself in your Zinn Digital® dashboard.'=>'இந்த தளத்தில் பயன்பாட்டு கடவுச்சொற்கள் முடக்கப்பட்டுள்ளன, எனவே எங்களால் நற்சான்றிதழை உருவாக்க முடியாது. அவற்றை இயக்க உங்கள் ஹோஸ்ட்டைக் கேளுங்கள், அல்லது உங்கள் Zinn Digital® கட்டுப்பாட்டுப் பலகத்தில் நீங்களே உருவாக்கும் கடவுச்சொல்லுடன் தளத்தை இணைக்கவும்.','WordPress would not create a credential for this site. Nothing has been sent anywhere.'=>'WordPress இந்த தளத்திற்கான நற்சான்றிதழை உருவாக்க முடியவில்லை. எங்கும் எதுவும் அனுப்பப்படவில்லை.','We could not reach Zinn Digital® from this site. Nothing was connected, and the credential we made has been removed. Check the site can make outgoing requests, and try again.'=>'இந்த தளத்திலிருந்து Zinn Digital®-ஐ அணுக முடியவில்லை. எதுவும் இணைக்கப்படவில்லை, மேலும் நாங்கள் உருவாக்கிய நற்சான்றிதழ் நீக்கப்பட்டது. தளம் வெளிச்செல்லும் கோரிக்கைகளைச் செய்ய முடியுமா என்பதைச் சரிபார்த்து, மீண்டும் முயற்சிக்கவும்.','Zinn Digital® could not finish connecting this site. The problem is on our side, not with your pairing code — nothing was connected, and the credential we made has been removed. The same pairing code still works: try again in a few minutes.'=>'Zinn Digital® தளத்தால் இந்த தளத்தை இணைத்து முடிக்க முடியவில்லை. சிக்கல் எங்கள் பக்கத்தில் உள்ளது, உங்களுடைய இணைக்கும் குறியீட்டில் இல்லை — எதுவும் இணைக்கப்படவில்லை, மேலும் நாங்கள் உருவாக்கிய நற்சான்றிதழ் அகற்றப்பட்டது. அதே இணைக்கும் குறியீடு இன்னும் செயல்படுகிறது: சில நிமிடங்களில் மீண்டும் முயற்சிக்கவும்.','Zinn Digital® did not accept that pairing code. Nothing was connected. Generate a fresh code in your dashboard and try again.'=>'Zinn Digital® அந்த இணைத்தல் குறியீட்டை ஏற்கவில்லை. எதுவும் இணைக்கப்படவில்லை. உங்கள் டாஷ்போர்டில் புதிய குறியீட்டை உருவாக்கி மீண்டும் முயற்சிக்கவும்.','Connected. Zinn Digital® can now publish to this site.'=>'இணைக்கப்பட்டது. Zinn Digital® இப்போது இந்தத் தளத்தில் வெளியிட முடியும்.','Connected'=>'இணைக்கப்பட்டது','Connecting…'=>'இணைக்கிறது…','Connected, but something needs attention'=>'இணைக்கப்பட்டது, ஆனால் ஏதோ கவனம் தேவைப்படுகிறது','Not connected'=>'இணைக்கப்படவில்லை','Running on your own account'=>'உங்கள் சொந்தக் கணக்கில் இயங்குகிறது','We could not check this'=>'இதை எங்களால் சரிபார்க்க முடியவில்லை','This plugin did not say why. Send a diagnostics report and we will look.'=>'இந்தச் செருகுநிரல் காரணத்தைக் குறிப்பிடவில்லை. கண்டறிதல் அறிக்கையை அனுப்பவும், நாங்கள் பார்க்கிறோம்.','Connection status'=>'இணைப்பு நிலை','Last checked %s ago.'=>'கடைசியாக %s முன்பு சோதிக்கப்பட்டது.','(opens in a new tab)'=>'(புதிய கீற்றில் திறக்கும்)','Send this to Zinn® support'=>'இதை Zinn® ஆதரவுக்கு அனுப்பவும்','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'சரியாக இதுவே அனுப்பப்படும் — வேறு எதுவும் இல்லை, மறைக்கப்பட்டதும் எதுவும் இல்லை. உங்கள் கடவுச்சொற்கள், டோக்கன்கள் மற்றும் API விசைகள் இதில் இல்லை.','The diagnostics report that will be sent'=>'அனுப்பப்படும் கண்டறியும் அறிக்கை','Copy to clipboard'=>'கிளிப்போர்டுக்கு நகலெடு','Send this report to Zinn® support'=>'இந்த அறிக்கையை Zinn® ஆதரவுக்கு அனுப்பவும்','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'நாங்கள் உங்களுக்காக ஒரு ஆதரவு டிக்கெட்டைத் திறந்து மின்னஞ்சல் மூலம் பதிலளிக்கிறோம். நீங்கள் அதை அனுப்ப விரும்பவில்லை என்றால், மேலே உள்ளதை நகலெடுத்து நீங்களே ஒரு டிக்கெட்டில் ஒட்டவும்.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'இந்த சேவையகத்திலிருந்து (%s) Zinn Digital®-ஐ அணுக முடியவில்லை. மேலே உள்ள அறிக்கையை நகலெடுத்து, அதற்குப் பதிலாக ஒரு டிக்கெட்டைத் திறக்கவும் — உங்கள் அமைப்புகளில் எந்தத் தவறும் இல்லை.','Sent. Zinn® support has your report and will reply by email.'=>'அனுப்பப்பட்டது. Zinn® ஆதரவுக் குழு உங்கள் அறிக்கையைப் பெற்றுள்ளது, மின்னஞ்சல் மூலம் பதிலளிக்கும்.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'அனுப்பப்பட்டது. Zinn® ஆதரவு உங்கள் அறிக்கையைப் பெற்றுள்ளது — குறிப்பு %s — மேலும் மின்னஞ்சல் மூலம் பதிலளிக்கும்.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'குறுகிய நேரத்தில் நீங்கள் பல அறிக்கைகளை அனுப்பியுள்ளீர்கள். சில நிமிடங்கள் காத்திருந்து மீண்டும் முயற்சிக்கவும் — முந்தையவை வந்து சேர்ந்துவிட்டன.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® ஆல் தற்போது அறிக்கையை ஏற்க முடியவில்லை — பிரச்சனை எங்கள் தரப்பில் உள்ளது, உங்கள் தரப்பில் அல்ல. சிறிது நேரத்தில் மீண்டும் முயற்சிக்கவும் அல்லது மேலே உள்ள அறிக்கையை ஒரு டிக்கெட்டில் நகலெடுக்கவும்.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'அறிக்கை நிராகரிக்கப்பட்டது (HTTP %d). அதை மேலே நகலெடுத்து, அந்த எண்ணைக் குறிப்பிட்டு ஒரு டிக்கெட்டைத் திறக்கவும்.','This site’s owner has turned off image uploads for Zinn Digital® in the Zinn® Connector settings.'=>'இந்த தளத்தின் உரிமையாளர் Zinn® Connector அமைப்புகளில் Zinn Digital®-க்கான படப் பதிவேற்றங்களை முடக்கியுள்ளார்.','This site’s owner has turned off edits to existing articles for Zinn Digital® in the Zinn® Connector settings.'=>'இந்த தளத்தின் உரிமையாளர் Zinn® Connector அமைப்புகளில் Zinn Digital®-க்கான ஏற்கனவே உள்ள கட்டுரைகளின் திருத்தங்களை முடக்கியுள்ளார்.','New article on your site: %s'=>'உங்கள் தளத்தில் புதிய கட்டுரை: %s','Zinn Digital® has added an article to your site.

Title: %1$s
Edit it: %2$s
Status: %3$s

Turn these emails off on the Zinn Digital® → Connector → Publishing screen.'=>'Zinn Digital® உங்கள் தளத்தில் ஒரு கட்டுரையைச் சேர்த்துள்ளது.

தலைப்பு: %1$s
இதைத் திருத்துக: %2$s
நிலை: %3$s

Zinn Digital® → இணைப்பான் → வெளியிடுதல் திரையில் இந்த மின்னஞ்சல்களை முடக்கவும்.','%s — guides and services'=>'%s — வழிகாட்டிகள் மற்றும் சேவைகள்','User guides'=>'பயனர் வழிகாட்டிகள்','Read the %s user guide'=>'%s பயனர் வழிகாட்டியைப் படிக்கவும்','Hide this'=>'இதை மறைக்கவும்','Zinn® hosting for WordPress'=>'WordPress-க்கான Zinn® ஹோஸ்டிங்','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, தினசரி காப்புப்பிரதிகள், இலவச இடம்பெயர்வு மற்றும் ஒன்றுக்கும் மேற்பட்ட தளங்களை நிர்வகிப்பவர்களுக்காக உருவாக்கப்பட்ட கட்டுப்பாட்டு பலகம்.','The Zinn® marketplace'=>'Zinn® சந்தை','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'இரு தரப்பும் திருப்தி அடையும் வரை பணம் பாதுகாப்பாக வைத்திருக்கப்படும் நிலையில், நிறுவப்பட்ட தளங்கள், டொமைன்கள் மற்றும் இணைப்பு இடவமைப்புகளை வாங்கி விற்கவும்.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — இதைத் தங்கள் வாழ்வாதாரமாகச் செய்யும் நபர்களை பணியமர்த்துங்கள்','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'எங்களின் உலகளாவிய ஃப்ரீலான்ஸ் சந்தை: எழுத்தாளர்கள், வடிவமைப்பாளர்கள், டெவெலப்பர்கள் மற்றும் SEO நிபுணர்களிடமிருந்து 10,000-க்கும் மேற்பட்ட ஆயத்த சேவைகளை உலாவுங்கள், அல்லது ஒரு திட்டத்தைப் பதிவிட்டு அவர்களை ஏலம் எடுக்க விடுங்கள்.','Connector'=>'இணைப்பான்','Connection'=>'இணைப்பு','Publishing'=>'வெளியிடுகிறது','Backups'=>'காப்புப்பிரதிகள்','Advanced'=>'மேம்பட்ட','Check the connection now'=>'இணைப்பை இப்போது சரிபார்க்கவும்','Disconnect this site'=>'இந்த தளத்தின் இணைப்பைத் துண்டிக்கவும்','This revokes the credential Zinn Digital® uses, so we can no longer publish to this site. Anything already published stays. Continue?'=>'இது Zinn Digital® பயன்படுத்தும் நற்சான்றிதழைத் திரும்பப் பெறுகிறது, எனவே எங்களால் இனி இந்தத் தளத்தில் வெளியிட முடியாது. ஏற்கனவே வெளியிடப்பட்டவை அனைத்தும் அப்படியே இருக்கும். தொடர விரும்புகிறீர்களா?','What we may do on this site'=>'இந்த தளத்தில் நாம் என்ன செய்யலாம்','The credential we hold is an ordinary WordPress application password, so WordPress itself decides what is possible. These narrow it further, on your side.'=>'நாங்கள் வைத்திருக்கும் நற்சான்றிதழ் ஒரு சாதாரண WordPress பயன்பாட்டு கடவுச்சொல் ஆகும், எனவே சாத்தியமானது எது என்பதை WordPress-ஏ தீர்மானிக்கிறது. இவை உங்கள் தரப்பில் அதை மேலும் சுருக்குகின்றன.','Publish articles as'=>'கட்டுரைகளை இவ்வாறு வெளியிடுக','Choose “a draft” if you would rather read everything before it goes live.'=>'எல்லாம் நேரலைக்கு வருவதற்கு முன் அனைத்தையும் படிக்க விரும்பினால், "வரைவு" என்பதைத் தேர்ந்தெடுக்கவும்.','Published straight away'=>'உடனடியாக வெளியிடப்பட்டது','A draft, for me to review'=>'நான் மதிப்பாய்வு செய்ய ஒரு வரைவு','Pending review'=>'மதிப்பாய்வு நிலுவையில் உள்ளது','Scheduled, using the date we send'=>'நாங்கள் அனுப்பும் தேதியைப் பயன்படுத்தி திட்டமிடப்பட்டது','Show the author as'=>'எழுத்தாளரை இவ்வாறு காட்டு','Which of your users appears as the author. This does not change who we sign in as.'=>'உங்கள் பயனர்களில் யார் ஆசிரியராகக் காட்டப்படுகிறார். நாங்கள் யாராக உள்நுழைகிறோம் என்பதை இது மாற்றாது.','Put articles in'=>'கட்டுரைகளை இதில் இடவும்','Allow images'=>'படங்களை அனுமதி','Let Zinn Digital® upload images into this site’s media library'=>'இந்த தளத்தின் ஊடக நூலகத்தில் படங்களைப் பதிவேற்ற Zinn Digital®-ஐ அனுமதிக்கவும்','Turn this off and articles arrive without their images. Nothing already uploaded is removed.'=>'இதை அணைக்கவும், கட்டுரைகள் அவற்றின் படங்கள் இல்லாமல் வரும். ஏற்கனவே பதிவேற்றப்பட்ட எதுவும் அகற்றப்படாது.','Allow edits'=>'திருத்தங்களை அனுமதிக்கவும்','Let Zinn Digital® update an article it published before'=>'முன்பு வெளியிட்ட கட்டுரையை Zinn Digital® புதுப்பிக்க அனுமதிக்கவும்','Used for corrections and re-optimisation. It never touches anything you wrote yourself.'=>'திருத்தங்கள் மற்றும் மறு உகப்பாக்கத்திற்குப் பயன்படுத்தப்படுகிறது. நீங்கள் சொந்தமாக எழுதிய எதையும் இது ஒருபோதும் மாற்றாது.','Tell me when something is published'=>'ஏதேனும் வெளியிடப்படும் போது எனக்குத் தெரிவிக்கவும்','Leave blank for no email. One message per article, from your own site.'=>'மின்னஞ்சல் தேவையில்லை எனில் காலியாக விடவும். உங்கள் சொந்த தளத்திலிருந்து ஒரு கட்டுரைக்கு ஒரு செய்தி.','Off-site backups'=>'ஆஃப்-சைட் காப்புப்பிரதிகள்','This site sends its own backup straight to Zinn® storage. Nothing passes through our servers on the way.'=>'இந்த தளம் தனது சொந்த காப்புப்பிரதியை நேரடியாக Zinn® சேமிப்பகத்திற்கு அனுப்புகிறது. வழியில் எங்கள் சேவையகங்கள் வழியாக எதுவும் செல்லாது.','Back this site up to Zinn Digital®'=>'இந்த தளத்தை Zinn Digital®-இல் காப்புநகலெடுக்கவும்','Backup token'=>'காப்பு டோக்கன்','Paste the token shown on this site’s Backups tab in your Zinn Digital® dashboard when you chose the plugin connection. It is shown there only once; saving the connection again issues a new one.'=>'செருகுநிரல் இணைப்பை நீங்கள் தேர்ந்தெடுத்தபோது, உங்கள் Zinn Digital® டாஷ்போர்டில் இந்த தளத்தின் காப்புப்பிரதிகள் தாவலில் காட்டப்பட்ட டோக்கனை ஒட்டவும். அது அங்கே ஒரு முறை மட்டுமே காட்டப்படும்; இணைப்பை மீண்டும் சேமிப்பது புதிய ஒன்றை வழங்கும்.','Leave these out'=>'இவற்றைத் தவிர்க்கவும்','One path per line, relative to wp-content — for example <code>cache</code> or <code>uploads/backups</code>. Caches and other backup plugins’ folders are the usual candidates.'=>'wp-content உடன் தொடர்புடைய ஒரு வரிக்கு ஒரு பாதை — உதாரணமாக <code>cache</code> அல்லது <code>uploads/backups</code>. இடைக்கால நினைவகம் (caches) மற்றும் பிற காப்புநகல் செருகுநிரல்களின் கோப்புறைகள் பொதுவான தேர்வுகளாகும்.','Stop if the archive would exceed'=>'காப்பகம் இதை விட அதிகமாக இருந்தால் நிறுத்தவும்','Megabytes. A shared host will usually kill a very large archive part-way; a bound turns that into a message instead of a silent failure.'=>'மெகாபைட்டுகள். ஒரு பகிர்வு ஹோஸ்ட் வழக்கமாக மிகப் பெரிய காப்பகத்தை பாதியிலேயே நிறுத்திவிடும்; ஒரு வரம்பு அதை அமைதியான தோல்விக்கு பதிலாக ஒரு செய்தியாக மாற்றுகிறது.','Detailed logging'=>'விரிவான பதிவேற்றம்','Record what this plugin does, for support'=>'ஆதரவிற்காக, இந்தச் செருகுநிரல் என்ன செய்கிறது என்பதைப் பதிவுசெய்க','Kept on this site, capped at the last 50 entries, and included in a diagnostics report. Turn it on before reproducing a problem.'=>'இந்த தளத்தில் வைக்கப்பட்டு, கடைசி 50 பதிவுகளுக்கு வரம்பிடப்பட்டு, கண்டறியும் அறிக்கையில் சேர்க்கப்பட்டுள்ளது. சிக்கலை மீண்டும் உருவாக்குவதற்கு முன் இதை இயக்கவும்.','On uninstall'=>'நிறுவல் நீக்கும் போது','Delete this plugin’s settings when it is uninstalled'=>'இந்தச் செருகுநிரல் நீக்கப்படும்போது அதன் அமைப்புகளை நீக்குக','Uninstalling never revokes the application password — that is deliberate, so uninstalling to try something else does not break your publishing. Use Disconnect above if you want the credential gone.'=>'நிரல்நீக்குவது பயன்பாட்டு கடவுச்சொல்லை ஒருபோதும் திரும்பப் பெறாது — இது வேண்டுமென்றே செய்யப்படுகிறது, எனவே வேறு எதையாவது முயற்சிப்பதற்காக நிரல்நீக்குவது உங்கள் வெளியீட்டைப் பாதிக்காது. அங்கீகாரச் சான்று நீக்கப்பட வேண்டுமெனில் மேலே உள்ள இணைப்பைத் துண்டி என்பதைப் பயன்படுத்தவும்.','The user we sign in as'=>'நாம் உள்நுழையும் பயனர்','The site’s default category'=>'தளத்தின் முன்னிருப்பு வகை','Connect this site again'=>'இந்த தளத்தை மீண்டும் இணைக்கவும்','Connect this site'=>'இந்த தளத்தை இணைக்கவும்','Open your Zinn Digital® dashboard, go to Content → Other sites, and press “Get a pairing code”. Paste it below.'=>'உங்கள் Zinn Digital® டாஷ்போர்டைத் திறந்து, உள்ளடக்கம் → பிற தளங்கள் என்பதற்குச் சென்று, “இணைத்தல் குறியீட்டைப் பெறுக” என்பதை அழுத்தவும். அதை கீழே ஒட்டவும்.','Connecting again creates a fresh credential and leaves the old one in place — use Disconnect first if you want the old one gone.'=>'மீண்டும் இணைப்பது புதிய நற்சான்றிதழை உருவாக்குகிறது மற்றும் பழையதை அப்படியே வைத்திருக்கிறது — பழையது நீக்கப்பட வேண்டும் என நீங்கள் விரும்பினால் முதலில் இணைப்பைத் துண்டி என்பதைப் பயன்படுத்தவும்.','Pairing code'=>'இணைத்தல் குறியீடு','It expires thirty minutes after you generate it, and can only be used once.'=>'நீங்கள் அதை உருவாக்கிய முப்பது நிமிடங்களுக்குப் பிறகு அதன் காலாவதியாகும், மேலும் அதை ஒரு முறை மட்டுமே பயன்படுத்த முடியும்.','You are not allowed to connect this site.'=>'இந்த தளத்தை இணைக்க உங்களுக்கு அனுமதி இல்லை.','This site is not connected to Zinn Digital®.'=>'இந்த தளம் Zinn Digital® உடன் இணைக்கப்படவில்லை.','Nothing is wrong — it has simply not been paired yet. Get a pairing code from your Zinn® dashboard and paste it into this plugin’s settings.'=>'எந்தப் பிரச்சனையும் இல்லை — இது இன்னும் இணைக்கப்படவில்லை, அவ்வளவே. உங்கள் Zinn® டாஷ்போர்டிலிருந்து இணைக்கும் குறியீட்டைப் பெற்று, இந்தச் செருகுநிரலின் அமைப்புகளில் ஒட்டவும்.','Open my Zinn® dashboard'=>'எனது Zinn® கட்டுப்பாட்டகத்தைத் திறக்கவும்','The connection is broken.'=>'இணைப்பு துண்டிக்கப்பட்டது.','The WordPress user the credential belonged to (%s) no longer exists on this site, so nothing we send can be published. Connect again as a user who can publish.'=>'சான்றுகள் சொந்தமாக இருந்த WordPress பயனர் (%s) இனி இந்த தளத்தில் இல்லை, எனவே நாங்கள் அனுப்பும் எதையும் வெளியிட முடியாது. வெளியிடக்கூடிய பயனராக மீண்டும் இணையவும்.','The “Zinn Digital® (publishing)” application password has been deleted from this site, so we can no longer sign in. Connect again to create a new one — nothing else was lost.'=>'இந்தத் தளத்திலிருந்து “Zinn Digital® (publishing)” பயன்பாட்டு கடவுச்சொல் நீக்கப்பட்டுவிட்டது, எனவே எங்களால் உள்நுழைய முடியவில்லை. புதிய ஒன்றை உருவாக்க மீண்டும் இணையுங்கள் — வேறு எதுவும் இழக்கப்படவில்லை.','See this site’s application passwords'=>'இந்த தளத்தின் பயன்பாட்டு கடவுச்சொற்களைப் பார்க்கவும்','Connected, but publishing would fail.'=>'இணைக்கப்பட்டது, ஆனால் வெளியிடுவது தோல்வியடையும்.','The credential belongs to %s, and that user can no longer publish posts. Sign-in still works, so nothing looks wrong until an article is due. Give that user the ability to publish, or connect again as somebody who can.'=>'சான்றளிப்பு %s-க்கு உரியது, மேலும் அந்தப் பயனரால் இனி இடுகைகளை வெளியிட முடியாது. உள்நுழைவு இன்னும் செயல்படுகிறது, எனவே ஒரு கட்டுரையை வெளியிடும் நேரம் வரும் வரை எதுவும் தவறாகத் தெரியாது. அந்தப் பயனருக்கு வெளியிடும் அனுமதியை வழங்கவும், அல்லது வெளியிட முடிந்த ஒருவராக மீண்டும் இணைக்கவும்.','Edit that user'=>'அந்தப் பயனரைத் திருத்துக','Connected here — we could not reach Zinn Digital® to confirm.'=>'இங்கே இணைக்கப்பட்டது — உறுதிப்படுத்த Zinn Digital®-ஐத் தொடர்பு கொள்ள முடியவில்லை.','Connected, but your Zinn® account needs attention.'=>'இணைக்கப்பட்டது, ஆனால் உங்கள் Zinn® கணக்கு கவனிப்பு தேவைப்படுகிறது.','Connected to Zinn Digital®.'=>'Zinn Digital® உடன் இணைக்கப்பட்டது.','Connected to Zinn Digital® as %s.'=>'%s ஆக Zinn Digital® உடன் இணைக்கப்பட்டுள்ளது.','Publishing as'=>'என வெளியிடுகிறது','Zinn® site ID'=>'Zinn® தள ஐடி','This server could not reach api.zinndigital.com (%s). That is usually a firewall or an outbound-connection rule on your host, not a problem with your Zinn® account — publishing may still be working.'=>'இந்தச் சேவையகத்தால் api.zinndigital.com (%s) ஐ அணுக முடியவில்லை. இது வழக்கமாக உங்கள் ஹோஸ்ட்டில் உள்ள ஃபயர்வால் அல்லது வெளிச்செல்லும் இணைப்பு விதியாகும், உங்கள் Zinn® கணக்கில் உள்ள சிக்கல் அல்ல — வெளியிடுதல் இன்னும் செயல்படக்கூடும்.','Zinn Digital® answered with an error of its own — that is our end, not yours. Publishing is unaffected while this clears.'=>'Zinn Digital® அதன் சொந்தப் பிழையுடன் பதிலளித்தது — இது எங்கள் பக்கத்தில் உள்ளது, உங்கள் பக்கத்தில் அல்ல. இது தீர்க்கப்படும் வரை வெளியிடுதல் பாதிக்கப்படாது.','Your Zinn® account is not currently able to publish to this site. Your dashboard says why.'=>'உங்கள் Zinn® கணக்கால் தற்போது இந்த தளத்தில் வெளியிட முடியாது. அதற்கான காரணம் உங்கள் டாஷ்போர்டில் குறிப்பிடப்பட்டுள்ளது.','Zinn Digital® answered HTTP %d, which we do not recognise. Send a diagnostics report from the Support tab and we will look — do not change anything here first.'=>'Zinn Digital® HTTP %d என பதிலளித்துள்ளது, இதை எங்களால் அடையாளம் காண முடியவில்லை. Support கீற்றிலிருந்து ஒரு கண்டறிதல் அறிக்கையை அனுப்புங்கள், நாங்கள் அதை ஆய்வு செய்கிறோம் — முதலில் இங்கு எதையும் மாற்ற வேண்டாம்.','Check again now'=>'இப்போது மீண்டும் சரிபார்க்கவும்','Checked. The connection is live.'=>'சரிபார்க்கப்பட்டது. இணைப்பு செயல்பாட்டில் உள்ளது.','We could not remove the application password, so this site is still connected. Delete “Zinn Digital® (publishing)” on your profile screen and try again — we have changed nothing.'=>'எங்களால் பயன்பாட்டு கடவுச்சொல்லை நீக்க முடியவில்லை, எனவே இந்த தளம் இன்னும் இணைக்கப்பட்டுள்ளது. உங்கள் சுயவிவரத் திரையில் “Zinn Digital® (publishing)” என்பதை நீக்கிவிட்டு மீண்டும் முயற்சிக்கவும் — நாங்கள் எதையும் மாற்றவில்லை.','Disconnected. The application password has been revoked, so Zinn Digital® can no longer publish to this site. Nothing already published was touched.'=>'இணைப்பு துண்டிக்கப்பட்டது. பயன்பாட்டு கடவுச்சொல் திரும்பப் பெறப்பட்டதால், Zinn Digital® இனி இந்த தளத்தில் வெளியிட முடியாது. ஏற்கனவே வெளியிடப்பட்ட எதுவும் மாற்றப்படவில்லை.','That file could not be read from this server, so nothing was uploaded.'=>'அந்தக் கோப்பை இந்தச் சேவையகத்திலிருந்து படிக்க முடியவில்லை, எனவே எதுவும் பதிவேற்றப்படவில்லை.','This site could not stream the upload, so nothing was sent.'=>'இந்த தளத்தால் பதிவேற்றத்தை ஸ்ட்ரீம் செய்ய முடியவில்லை, எனவே எதுவும் அனுப்பப்படவில்லை.','This file is %1$s and this site\'s PHP has no cURL, so the largest it can upload is %2$s.'=>'இந்தக் கோப்பு %1$s மற்றும் இந்தத் தளத்தின் PHP-யில் cURL இல்லை, எனவே பதிவேற்றக்கூடிய அதிகபட்ச அளவு %2$s ஆகும்.','The upload could not be completed.'=>'பதிவேற்றத்தை நிறைவுசெய்ய முடியவில்லை.','Storage refused the upload (HTTP %d).'=>'சேமிப்பகம் பதிவேற்றத்தை நிராகரித்துவிட்டது (HTTP %d).','Style preset'=>'பாணி முன்னமைவு','A starting point. Anything below overrides it.'=>'ஒரு தொடக்கப் புள்ளி. கீழே உள்ள எதுவும் இதை மேலெழுதும்.','Use my own colours and sizes'=>'எனது சொந்த நிறங்கள் மற்றும் அளவுகளைப் பயன்படுத்தவும்','Leave this off and the preset is used exactly as it is.'=>'இதை முடக்கி வையுங்கள், முன்னமைவு அது உள்ளபடியே பயன்படுத்தப்படும்.','See the Zinn Digital® release notes.'=>'Zinn Digital® வெளியீட்டுக் குறிப்புகளைப் பார்க்கவும்.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'இந்த புதுப்பித்தலுக்கான பதிவிறக்க இணைப்பை Zinn® புதுப்பித்தல் சேவை வழங்கவில்லை. இந்த தளம் Zinn® தளத்தை அணுக முடிகிறதா என்பதைச் சரிபார்த்து, பின்னர் மீண்டும் முயற்சிக்கவும்.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Zinn® புதுப்பிப்பு சேவையிலிருந்து (%s) புதுப்பிப்பைப் பதிவிறக்க முடியவில்லை. சில நிமிடங்களில் மீண்டும் முயற்சிக்கவும்.','The downloaded update failed its integrity check and was not installed.'=>'பதிவிறக்கப்பட்ட புதுப்பிப்பு அதன் நம்பகத்தன்மை சரிபார்ப்பில் தோல்வியடைந்தது மற்றும் நிறுவப்படவில்லை.']];